import{_ as a,o as t,c as i,ap as o}from"./chunks/framework.CuFS6FqL.js";const s="/images/yubikey_gpg_keygrip.png",y=JSON.parse('{"title":"YubiKey setup","description":"One-time setup of a YubiKey for PIV/SSH (key generation and certificate).","frontmatter":{"title":"YubiKey setup","description":"One-time setup of a YubiKey for PIV/SSH (key generation and certificate)."},"headers":[],"relativePath":"organization/human-resources/yubikey-setup.md","filePath":"organization/human-resources/yubikey-setup.md"}'),r={name:"organization/human-resources/yubikey-setup.md"};function n(p,e,l,u,c,d){return t(),i("div",null,[...e[0]||(e[0]=[o('<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /organization/human-resources/yubikey-setup.md for this page in Markdown format</div><h1 id="yubikey-setup" tabindex="-1">YubiKey setup <a class="header-anchor" href="#yubikey-setup" aria-label="Permalink to &quot;YubiKey setup&quot;">​</a></h1><p>Do this once when you receive a new YubiKey. After that, configure each PC separately: <a href="./yubikey-pc-setup">YubiKey PC setup</a>.</p><p>Verify that you have a <a href="https://www.yubico.com/genuine/" target="_blank" rel="noreferrer">genuine YubiKey</a>.</p><h2 id="piv" tabindex="-1">PIV <a class="header-anchor" href="#piv" aria-label="Permalink to &quot;PIV&quot;">​</a></h2><p>Prerequisites:</p><ul><li>Install <a href="https://github.com/Yubico/yubikey-manager/releases/latest" target="_blank" rel="noreferrer">YubiKey Manager CLI</a></li><li>Have your PIN and Management Key ready (store in Vaultwarden)</li><li>Use a supported algorithm (see <a href="#supported-algorithms">Supported algorithms</a> below)</li></ul><p>You must set your <code>pin-policy</code> at key creation. You cannot change it afterwards (you must create new keys). Use <code>once</code> (not <code>always</code>) if you need <a href="./yubikey-pc-setup#agent-forwarding">agent forwarding</a>.</p><ol><li>Generate a keypair (select one of the working algos: prefer <code>eccp384</code> over <code>rsa3072</code> over <code>rsa2048</code>):</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ykman piv keys generate --touch-policy never --pin-policy once -a eccp384 9a pubkey.pem</span></span></code></pre></div><ol start="2"><li>Create a self signed cert based on this key:</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ykman piv certificates generate 9a pubkey.pem --subject &quot;CN=SSH Key&quot; --valid-days 36500</span></span></code></pre></div><ol start="3"><li>On a PC with OpenSC installed (see <a href="./yubikey-pc-setup">YubiKey PC setup</a>), retrieve your public key and add it to <code>~/.ssh/authorized_keys</code> on the remote host:</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ssh-keygen -D &quot;C:\\Program Files\\OpenSC Project\\OpenSC\\pkcs11\\opensc-pkcs11.dll&quot;</span></span></code></pre></div><h3 id="supported-algorithms" tabindex="-1">Supported algorithms <a class="header-anchor" href="#supported-algorithms" aria-label="Permalink to &quot;Supported algorithms&quot;">​</a></h3><p>Known working algos are:</p><ul><li>rsa1024 (probably, pls don&#39;t use)</li><li>rsa2048 (default)</li><li>rsa3072</li><li>eccp384 (sign-only, no de/encryption, prefer this for ssh)</li></ul><p>Unsupported (or known to fail):</p><ul><li>rsa4096</li><li>ed25519</li><li>x25519 (failed on certificate creation)</li></ul><h2 id="gpg" tabindex="-1">GPG <a class="header-anchor" href="#gpg" aria-label="Permalink to &quot;GPG&quot;">​</a></h2><h3 id="create-openpgp-key" tabindex="-1">Create OpenPGP Key <a class="header-anchor" href="#create-openpgp-key" aria-label="Permalink to &quot;Create OpenPGP Key&quot;">​</a></h3><p>You can create a GPG-Key (e.g. for Sysreptor Archiving) as described here: <a href="https://docs.sysreptor.com/insights/archiving#how-to-use" target="_blank" rel="noreferrer">Archiving | SysReptor</a> (Tab: &quot;Generate private keys on YubiKey 5&quot;).</p><p>List your Public-Key with</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ssh-add -L</span></span></code></pre></div><p>If the command returns &quot;<code>The agent has no identities.</code>&quot;, make sure you complete the <a href="./yubikey-pc-setup#gpg">YubiKey-PC-Setup</a> first.</p><p>For every Key you want to use as a SSH-Key add its Keygrip to <code>C:\\Users&lt;user&gt;\\AppData\\Roaming\\gnupg\\sshcontrol</code>.<br><img src="'+s+'" alt="Add Keygrip to sshcontrol file">.</p>',26)])])}const g=a(r,[["render",n]]);export{y as __pageData,g as default};
